def rows(row_count):
    if row_count < 0:
        raise ValueError("number of rows is negative")
    if row_count == 0:
        return []
    if row_count == 1:
        return [[1]]

    previous = rows(row_count - 1)
    last = previous[-1]
    # build next row by summing adjacent pairs, with 1s at ends
    next_row = [1]
    for i in range(len(last) - 1):
        next_row.append(last[i] + last[i + 1])
    next_row.append(1)

    return previous + [next_row]
